MasteringComponent::~MasteringComponent(){stylePreset.setLookAndFeel(nullptr);targetPreset.setLookAndFeel(nullptr);setLookAndFeel(nullptr);cancel();if(worker&&worker->joinable())worker->join();saveRecoverySession();beforeTransport.setSource(nullptr);afterTransport.setSource(nullptr);if(previewIsTemporary&&previewFile.existsAsFile())previewFile.deleteFile();shutdownAudio();}
void MasteringComponent::prepareToPlay(int n,double r){playbackSampleRate=r;beforePlaybackBuffer.setSize(2,n);afterPlaybackBuffer.setSize(2,n);beforeTransport.prepareToPlay(n,r);afterTransport.prepareToPlay(n,r);}void MasteringComponent::releaseResources(){beforeTransport.releaseResources();afterTransport.releaseResources();beforePlaybackBuffer.setSize(0,0);afterPlaybackBuffer.setSize(0,0);}void MasteringComponent::getNextAudioBlock(const juce::AudioSourceChannelInfo&i){if(!i.buffer||i.numSamples<=0)return;const auto channels=juce::jmax(1,i.buffer->getNumChannels());beforePlaybackBuffer.setSize(channels,i.numSamples,false,false,true);afterPlaybackBuffer.setSize(channels,i.numSamples,false,false,true);beforePlaybackBuffer.clear();afterPlaybackBuffer.clear();juce::AudioSourceChannelInfo beforeInfo(&beforePlaybackBuffer,0,i.numSamples),afterInfo(&afterPlaybackBuffer,0,i.numSamples);beforeTransport.getNextAudioBlock(beforeInfo);afterTransport.getNextAudioBlock(afterInfo);const auto requestedBlend=targetMasteredBlend.load();const auto gain=masteredPlaybackGain.load();const auto requestedMonitorGain=monitorGain.load();const auto step=1.0f/static_cast<float>(juce::jmax(1.0,playbackSampleRate*0.01));for(int sample=0;sample<i.numSamples;++sample){if(currentMasteredBlend<requestedBlend)currentMasteredBlend=juce::jmin(requestedBlend,currentMasteredBlend+step);else if(currentMasteredBlend>requestedBlend)currentMasteredBlend=juce::jmax(requestedBlend,currentMasteredBlend-step);if(currentMonitorGain<requestedMonitorGain)currentMonitorGain=juce::jmin(requestedMonitorGain,currentMonitorGain+step);else if(currentMonitorGain>requestedMonitorGain)currentMonitorGain=juce::jmax(requestedMonitorGain,currentMonitorGain-step);for(int channel=0;channel<channels;++channel){const auto originalSample=beforePlaybackBuffer.getSample(channel,sample);const auto masteredSample=afterPlaybackBuffer.getSample(channel,sample)*gain;const auto auditionSample=originalSample*(1.0f-currentMasteredBlend)+masteredSample*currentMasteredBlend;i.buffer->setSample(channel,i.startSample+sample,auditionSample*currentMonitorGain);}}const auto db=[](float v){return juce::Decibels::gainToDecibels(v,-100.0f);};const auto measure=[&](int channel,bool rms){const auto c=juce::jmin(channel,i.buffer->getNumChannels()-1);return rms?i.buffer->getRMSLevel(c,i.startSample,i.numSamples):i.buffer->getMagnitude(c,i.startSample,i.numSamples);};playbackMeter.setLevels(db(measure(0,false)),db(measure(1,false)),db(measure(0,true)),db(measure(1,true)));}
